def equation(gate_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Equação empírica para log10(|ID|/A) ao longo da curva de transferência."""
    # Import the sigmoid function for non-linear relationships
    from scipy.special import sigmoid

    return 10 * np.log10(parameters[0] + parameters[1] * sigmoid(gate_voltage_abs))
